func test_history_recording(history_list: Array[Dictionary], line_data: Dictionary) -> bool:
	if line_data.is_empty():
		return false

	var initial_count: int = history_list.size()
	history_list.append(line_data)

	if history_list.size() != initial_count + 1:
		return false

	var last_entry: Dictionary = history_list.back()
